import pytestfrom vpars_bot.domain import Filters, UserError, excluded_values, parse_keywordsfrom vpars_bot.formatting import filter_namedef test_comma_input_normalization_and_complete_name():    values = parse_keywords(" Nike , hoodie , л, nike, бавовна ")    assert values == ["Nike", "hoodie", "L", "бавовна"]    filters = Filters(keywords=values, keywords_all=True, sources={"vinted_fr": ["FR"]})    assert filter_name(filters.model_dump()) == "Nike, hoodie, L, бавовна"def test_jeans_keywords_normalize_waist_notation_and_deduplicate():    values = parse_keywords("Gucci, Jeans, w32, W 32, Very Good")    assert values == ["Gucci", "Jeans", "W32", "Very Good"]    filters = Filters(keywords=values, keywords_all=True, sources={"vinted_fr": ["FR"]})    assert filter_name(filters.model_dump()) == "Gucci, Jeans, W32, Very Good"@pytest.mark.parametrize(    "text",    [        "",        " , ",        "Nike,,L",        "!!!",        "a" * 101,        ",".join(str(i) for i in range(9)),        ",".join(letter * 100 for letter in "abcd"),    ],)def test_invalid_input_cannot_create_a_broad_or_unbounded_filter(text):    with pytest.raises(UserError):        parse_keywords(text)def test_keyword_mode_cannot_silently_retain_old_typed_fields():    with pytest.raises(UserError):        Filters(            keywords=["Nike"], keywords_all=True, brands=["Adidas"], sources={"vinted_fr": ["FR"]}        )def test_exclusions_normalize_and_survive_country_conversion(registry):    values = excluded_values([" Fake ", "fake", "kids.", "Small hole"])    assert values == ["Fake", "kids", "Small hole"]    filters = Filters(        keywords=["Nike"],        keywords_all=True,        excluded_keywords=values,        sources={"vinted_fr": ["FR"]},    )    assert registry.for_source(filters, "vinted_fr").excluded_keywords == values    for values in ([""], ["!!!"], ["x" * 101], [str(i) for i in range(21)]):        with pytest.raises(UserError):            excluded_values(values)def test_in_progress_price_draft_survives_exclusion_step_upgrade(registry):    from vpars_bot.keyword_dialog import build_filters, input_value, upgrade_draft    draft = upgrade_draft(        {            "kind": "keyword_filter",            "keywords": ["Nike"],            "step": "maximum:GBP",            "bounds": {},            "currencies": ["EUR", "GBP"],        },        registry,    )    draft = input_value(draft, "", 1, skip=True)    assert build_filters(draft, registry).excluded_keywords == []@pytest.mark.parametrize("source,currency", [("vinted_fr", "EUR"), ("vinted_gb", "GBP")])def test_legacy_keyword_prices_use_euro_bounds_for_all_currencies(registry, source, currency):    prices = {        "EUR": {"minimum": "20", "maximum": "80"},        "GBP": {"minimum": "10", "maximum": "60"},    }    filters = Filters(        keywords=["Nike", "L"],        keywords_all=True,        sources={"vinted_fr": ["FR"], "vinted_gb": ["GB"]},        native_prices=prices,    )    result = registry.for_source(filters, source)    assert result.keywords_all and result.keywords == ["Nike", "L"]    expected = prices["EUR"] if currency == "EUR" else {"minimum": "17.00", "maximum": "68.00"}    assert result.price.model_dump(mode="json") == {**expected, "currency": currency}    assert result.native_prices == {}